Instead of making every stone a DSU node, I make each used row and column a node. A stone at `(r, c)` joins row `r` to a shifted column node. The shift keeps row numbers and column numbers separate.

For example, with stones `[[0,0], [0,1], [2,2]]`, the first two unions share row `0`, so they are in one component. The third stone is another component. With three stones and two components, the answer is `1`.

```cpp
class Solution {
public:
    vector<int> parent;
    vector<int> size;

    int findRoot(int node) {
        if (parent[node] == node) {
            return node;
        }
        return parent[node] = findRoot(parent[node]);
    }

    void unite(int first, int second) {
        first = findRoot(first);
        second = findRoot(second);

        if (first == second) {
            return;
        }

        if (size[first] < size[second]) {
            swap(first, second);
        }

        parent[second] = first;
        size[first] += size[second];
    }

    int maxRemove(vector<vector<int>>& stones, int n) {
        const int offset = 10001;
        parent.resize(20002);
        size.assign(20002, 1);

        for (int i = 0; i < 20002; i++) {
            parent[i] = i;
        }

        vector<bool> used(20002, false);

        for (const vector<int>& stone : stones) {
            int rowNode = stone[0];
            int columnNode = stone[1] + offset;

            unite(rowNode, columnNode);
            used[rowNode] = true;
            used[columnNode] = true;
        }

        int components = 0;
        for (int node = 0; node < 20002; node++) {
            if (used[node] && findRoot(node) == node) {
                components++;
            }
        }

        return n - components;
    }
};
```

The input is only read, not modified. The fixed DSU size matches the coordinate range used by the problem.

Time complexity: `O(n * alpha(n))` for the unions and root checks.
Space complexity: `O(1)` with respect to `n`, using the fixed coordinate range, or `O(n)` if the coordinate range is treated as input-dependent.

The useful observation is that the actual coordinate values do not matter for the graph. I store the stone indexes in a list for each row and column. The DFS then follows those lists and counts components.

Dry run for `[[0, 0], [0, 1], [2, 2]]`: the first two stones form one group, while the last stone is alone. There are two components, so the result is `3 - 2 = 1`.

```python
class Solution:
    def maxRemove(self, stones, n):
        rows = {}
        columns = {}

        for index, (row, column) in enumerate(stones):
            rows.setdefault(row, []).append(index)
            columns.setdefault(column, []).append(index)

        visited = [False] * n
        components = 0

        def dfs(start):
            stack = [start]
            while stack:
                current = stack.pop()
                if visited[current]:
                    continue

                visited[current] = True
                row, column = stones[current]

                for next_index in rows[row]:
                    if not visited[next_index]:
                        stack.append(next_index)

                for next_index in columns[column]:
                    if not visited[next_index]:
                        stack.append(next_index)

        for index in range(n):
            if not visited[index]:
                dfs(index)
                components += 1

        return n - components
```

If no rows or columns repeat, every stone becomes its own component and nothing can be removed.

Time complexity: `O(n)`, because each stone and each row or column link is processed a limited number of times.
Space complexity: `O(n)`.

Kept the graph very direct here. Each stone is a node, and two nodes are connected when their row or column matches. A DFS counts how many connected groups exist, then the answer is the number of stones minus the number of groups.

```cpp
class Solution {
public:
    void dfs(int index, vector<vector<int>>& stones, vector<bool>& visited) {
        visited[index] = true;

        for (int next = 0; next < stones.size(); next++) {
            if (visited[next]) {
                continue;
            }

            if (stones[index][0] == stones[next][0] ||
                stones[index][1] == stones[next][1]) {
                dfs(next, stones, visited);
            }
        }
    }

    int maxRemove(vector<vector<int>>& stones, int n) {
        vector<bool> visited(n, false);
        int components = 0;

        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                dfs(i, stones, visited);
                components++;
            }
        }

        return n - components;
    }
};
```

Time complexity: `O(n^2)`, since each DFS step may scan all stones.
Space complexity: `O(n)` for the visited array and recursion stack.

I used maps for rows and columns so DFS can jump straight to related stones instead of checking every pair. A stone is visited once. After one group is finished, one stone from that group must remain, so each group reduces the answer by one.

```java
class Solution {
    public int maxRemove(int[][] stones, int n) {
        java.util.Map<Integer, java.util.List<Integer>> rows = new java.util.HashMap<>();
        java.util.Map<Integer, java.util.List<Integer>> columns = new java.util.HashMap<>();

        for (int i = 0; i < n; i++) {
            rows.computeIfAbsent(stones[i][0], key -> new java.util.ArrayList<>()).add(i);
            columns.computeIfAbsent(stones[i][1], key -> new java.util.ArrayList<>()).add(i);
        }

        boolean[] visited = new boolean[n];
        int components = 0;

        for (int i = 0; i < n; i++) {
            if (visited[i]) {
                continue;
            }

            components++;
            java.util.ArrayDeque<Integer> stack = new java.util.ArrayDeque<>();
            stack.push(i);

            while (!stack.isEmpty()) {
                int current = stack.pop();
                if (visited[current]) {
                    continue;
                }

                visited[current] = true;
                int row = stones[current][0];
                int column = stones[current][1];

                for (int next : rows.get(row)) {
                    if (!visited[next]) {
                        stack.push(next);
                    }
                }

                for (int next : columns.get(column)) {
                    if (!visited[next]) {
                        stack.push(next);
                    }
                }
            }
        }

        return n - components;
    }
};
```

The single-stone case is covered automatically, because it creates one component and returns zero.

Time complexity: `O(n)` on the usual row and column lists, counting each stored connection while traversing.
Space complexity: `O(n)` for the maps, visited array, and stack.

This version starts with every stone in its own set. Whenever two stones share a row or column, their sets are joined. The number of successful joins tells us how many stones can be removed directly.

```java
class Solution {
    private int[] parent;

    private int find(int node) {
        if (parent[node] != node) {
            parent[node] = find(parent[node]);
        }
        return parent[node];
    }

    private boolean union(int first, int second) {
        int rootFirst = find(first);
        int rootSecond = find(second);

        if (rootFirst == rootSecond) {
            return false;
        }

        parent[rootSecond] = rootFirst;
        return true;
    }

    public int maxRemove(int[][] stones, int n) {
        parent = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
        }

        int components = n;

        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                boolean sameRow = stones[i][0] == stones[j][0];
                boolean sameColumn = stones[i][1] == stones[j][1];

                if ((sameRow || sameColumn) && union(i, j)) {
                    components--;
                }
            }
        }

        return n - components;
    }
};
```

This does not change the input array. It also handles repeated connections safely, because a union that finds the same root does not reduce the component count twice.

Time complexity: `O(n^2 * alpha(n))`, from checking every pair and using DSU operations.
Space complexity: `O(n)` for the parent array.
